<template>
 <section class="qvs-page" :data-variant="appearance.variant" aria-labelledby="qvs-title">
  <header class="qvs-hero"><div><span class="qvs-kicker">QGAUSS / LET YOUR WORDS FIND A VOICE</span><h1 id="qvs-title">{{ vt("把心里的文字，") }}<em>{{ vt("说给世界听。") }}</em></h1><p>{{ vt("给故事一点温度，给好点子一段被听见的时间。") }}</p><router-link to="/voice">{{ vt("去声音收藏室，重听一次喜欢的回响") }} <ClientIcon name="arrowUpRight"/></router-link></div><div class="qvs-headphones" aria-hidden="true"><i></i><i></i><b>♪</b><span>GOOD WORDS, GOOD VIBES</span></div></header>
  <p v-if="state.notice" class="qvs-notice" role="status">{{ vt(state.notice) }}</p><p v-if="state.error" class="qvs-error" role="alert">{{ vt(state.error) }}</p>
  <div v-if="state.loading" class="qvs-loading" role="status"><QLoader text="" :size="29"/>{{ vt("正在打开声音工作室…") }}</div>
  <p v-else-if="!state.options?.speech?.ready" class="qvs-unavailable" role="status">{{ vt(state.options?.speech?.reason)||vt("创作搭档尚未接通，可以先把文字留在这里。") }}<button type="button" @click="work.loadOptions">{{ vt("重新读取") }}</button></p>
  <div class="qvs-workspace">
   <section class="qvs-writing" :aria-label="vt(&quot;配音文字&quot;)"><header><div><span class="qvs-kicker">FIRST, A LITTLE SOMETHING TO SAY</span><h2>{{ vt("今天，想说点什么？") }}</h2></div><span class="qvs-paper-stamp" aria-hidden="true">✳</span></header><label class="qvs-title-input">{{ vt("给这段声音起个名字") }}<input v-model="state.draft.title" maxlength="80" :placeholder="vt(&quot;例如：写给明天的自己&quot;)"/></label><label class="qvs-text-input"><span>{{ vt("写下要说的话") }} <small>{{ vt("{p0} / {p1} 字符",{p0:state.draft.text.length,p1:state.options?.maxSpeechChars||16000}) }}</small></span><textarea v-model="state.draft.text" maxlength="32768" rows="13" :placeholder="vt(&quot;把故事、旁白、小计划，或一句想认真说的话，放在这里。&quot;)"/></label><footer><span><i></i>{{ vt("草稿留在当前账号的此窗口中") }}</span><button type="button" class="qvs-clear" :disabled="!state.draft.text&&!state.draft.title" @click="state.clearReview=true">{{ vt("整理这张纸") }}</button></footer></section>
   <aside class="qvs-voices" :aria-label="vt(&quot;选择配音音色&quot;)"><header><span class="qvs-kicker">A VOICE THAT FEELS RIGHT</span><h2>{{ vt("挑一种，") }}<em>{{ vt("喜欢的语气。") }}</em></h2><p>{{ vt("同一段文字，也有不同的温度。") }}</p></header><div class="qvs-voice-grid"><button v-for="voice in VOICES" :key="voice.id" type="button" :aria-pressed="state.draft.voice===voice.id" :style="{'--voice-color':voice.color}" @click="state.draft.voice=voice.id"><span class="qvs-voice-orb" aria-hidden="true">{{ voice.id==='fable'?'◡':voice.id==='nova'?'✦':voice.id==='echo'?'◉':voice.id==='onyx'?'◒':voice.id==='shimmer'?'✧':'⌁' }}</span><span><strong>{{ vt(voice.name) }}</strong><small>{{ vt(voice.mood) }}</small></span><i>{{ state.draft.voice===voice.id?'✓':'+' }}</i></button></div><div class="qvs-voice-note"><p>{{ vt(selectedVoice.note) }}</p><button type="button" :disabled="busy||!!state.offer||!state.options?.speech?.ready" @click="work.quote(true)"><ClientIcon name="microphone"/>{{ vt("先听听{p0}的声音",{p0:vt(selectedVoice.name)}) }}</button><small>{{ vt("试听使用固定介绍文字，也会先确认本站次数。") }}</small></div></aside>
   <section class="qvs-session" :aria-label="vt(&quot;声音创作与回放&quot;)"><div class="qvs-console-art" :class="{'is-playing':state.playing,'is-working':busy}" aria-hidden="true"><div class="qvs-record"><i></i><b>Q</b></div><div class="qvs-wave"><i v-for="n in 23" :key="n" :style="{'--bar':n}"></i></div><span>{{ busy?'A LITTLE MAGIC, IN THE MAKING':'YOUR WORDS. YOUR OWN LITTLE WORLD.' }}</span></div>
    <div class="qvs-session-body"><span class="qvs-kicker">{{ state.task?.status==='COMPLETED'?'ONE LITTLE MOMENT, SAVED':state.task?'LET YOUR WORDS FIND THEIR RHYTHM':'MAKE A LITTLE ROOM FOR SOUND' }}</span><h2>{{ state.task?vt(voiceTaskLabel(state.task)):state.pending?vt("先把这一次声音，核对好。"):vt("好文字，值得被好好听见。") }}</h2><p v-if="state.task">{{ state.task.sourceKind==='sample'?vt("音色试听"):state.task.label||vt("这一段声音") }} · {{ vt(voiceName(state.task.voice)) }}</p><p v-else>{{ vt("准备好后，核对文字、音色和次数，再让创作开始。") }}</p>
     <template v-if="state.task"><div v-if="!voiceTerminal(state.task)" class="qvs-progress" role="status"><QLoader text="" :size="22"/><span>{{ vt("已完成 {p0} / {p1} 段 · {p2}%",{p0:state.task.completedSegments||0,p1:state.task.segmentCount||1,p2:state.task.progress||0}) }}</span></div><div v-if="(state.task.status==='COMPLETED'&&state.task.audio?.length)||state.task.streamUrl&&!voiceTerminal(state.task)" class="qvs-player"><p v-if="state.task.streamUrl" class="qvs-stream-status" role="status"><span class="qvs-live-wave" :class="{active:state.playbackRequested}" aria-hidden="true"><i v-for="bar in 5" :key="bar" :style="{'--voice-bar':bar}"></i></span>{{ vt(voicePlaybackLabel(state.streamPhase,state.task)) }}</p><div class="qvs-player-controls"><button type="button" class="qvs-play" :disabled="state.stopping" :aria-label="state.playbackRequested?vt(&quot;暂停这段配音&quot;):vt(&quot;播放这段配音&quot;)" @click="work.play"><QLoader text="" v-if="state.audioLoading" :size="24"/><span v-else>{{ state.playbackRequested?'Ⅱ':'▶' }}</span></button><div><strong v-if="state.streaming">{{ vt("整段连续播放") }}</strong><strong v-else-if="state.task.audio.length">{{ vt("第 {p0} / {p1} 段",{p0:state.part+1,p1:state.task.audio.length}) }}</strong><strong v-else>{{ vt("等待第一段声音") }}</strong><small>{{ voiceDuration(state.playbackSeconds) }} / {{ state.playbackDuration?voiceDuration(state.playbackDuration):!voiceTerminal(state.task)?vt("接收中"):'--:--' }}</small></div><button type="button" :aria-label="vt(&quot;上一段配音&quot;)" :disabled="state.stopping||state.streaming||!state.part||state.audioLoading" @click="work.playPart(state.part-1)">‹</button><button type="button" :aria-label="vt(&quot;下一段配音&quot;)" :disabled="state.stopping||state.streaming||state.part+1>=state.task.audio.length||state.audioLoading" @click="work.playPart(state.part+1)">›</button></div><input type="range" min="0" :max="state.playbackDuration||0" :value="state.playbackSeconds" step="0.1" :aria-label="vt(&quot;配音播放进度&quot;)" :disabled="(!state.audioUrl&&!state.streaming)||!state.playbackDuration" @input="work.seek($event.target.value)"/><label class="qvs-speed">{{ vt("播放语速") }}<select v-model.number="state.playbackRate"><option :value=".75">0.75 ×</option><option :value="1">1 ×</option><option :value="1.25">1.25 ×</option><option :value="1.5">1.5 ×</option></select><small>{{ vt("只改变回放，不重新生成。") }}</small></label></div><p v-if="state.streamNotice" class="qvs-stream-notice" role="status">{{ vt(state.streamNotice) }}</p><p v-if="state.task.errorMessage" class="qvs-inline-error" role="status">{{ vt(state.task.errorMessage) }}</p><div v-if="state.task.billing" class="qvs-billing"><span>{{ vt("已使用") }} <b>{{ vt("{p0} 次",{p0:state.task.billing.charged||0}) }}</b></span><span v-if="state.task.billing.reserved">{{ vt("当前预留") }} <b>{{ vt("{p0} 次",{p0:state.task.billing.reserved}) }}</b></span><span v-if="state.task.billing.returned">{{ vt("已退回") }} <b>{{ vt("{p0} 次",{p0:state.task.billing.returned}) }}</b></span><span v-if="state.task.billing.expired">{{ vt("已到期") }} <b>{{ vt("{p0} 次",{p0:state.task.billing.expired}) }}</b></span></div></template>
     <div class="qvs-session-actions"><button v-if="state.playbackReconnectable" type="button" class="qvs-secondary" :disabled="state.stopping" @click="work.reconnectPlayback">{{ vt("重新连接播放") }}</button><button v-if="!state.pending||state.task&&voiceTerminal(state.task)" type="button" class="qvs-primary" :disabled="busy||!!state.offer||!state.draft.text.trim()||!state.options?.speech?.ready" @click="work.quote(false)">{{ vt("让文字，慢慢响起来") }} <ClientIcon name="arrowUpRight"/></button><template v-if="state.pending&&state.stage==='unknown'"><button type="button" class="qvs-primary" @click="work.check">{{ vt("核对原任务") }}</button><button type="button" class="qvs-secondary" @click="work.retry">{{ vt("重试原提交") }}</button></template><button v-if="state.pending||state.task&&!voiceTerminal(state.task)" type="button" class="qvs-secondary" :disabled="state.stopping" @click="work.stop">{{ state.stopping?vt("正在确认停止结果…"):state.task?vt("请求停止生成"):vt("结束这次等待") }}</button><button v-if="state.task?.status==='COMPLETED'&&state.task.audio?.length" type="button" class="qvs-secondary" :disabled="state.downloading" @click="work.download"><QLoader text="" v-if="state.downloading" :size="19"/>{{ state.downloading?vt("正在整理整段声音…"):vt("保存完整配音") }}</button><router-link v-if="state.task" to="/voice" class="qvs-text-link">{{ vt("在声音收藏室找到它") }} <ClientIcon name="arrowUpRight"/></router-link></div><p class="qvs-disclosure">{{ vt("合成声音 · 本站次数以生成回执为准。重听和保存已经完成的声音，不会重新生成或扣次。") }}</p>
    </div><audio ref="audio" preload="none"></audio>
   </section>
  </div>
  <dialog ref="review" class="qvs-review" aria-labelledby="qvs-review-title" @cancel.prevent="work.reject"><template v-if="state.offer"><span class="qvs-kicker">ONE LAST LOOK, THEN LET IT SING</span><h2 id="qvs-review-title">{{ state.offer.payload.sample?vt("先听一小段，感受它的语气。"):vt("让这段文字，拥有自己的声音。") }}</h2><div class="qvs-offer-title"><b>{{ vt(voiceName(state.offer.payload.voice)) }}</b><span>{{ state.offer.payload.sample?vt("固定介绍文字"):state.offer.payload.title||vt("这一次配音") }}</span></div><div v-if="!state.offer.payload.sample" class="qvs-offer-text">{{ state.offer.payload.text }}</div><div v-if="state.offer.loading" class="qvs-offer-loading" role="status"><QLoader text="" :size="23"/>{{ vt("正在确认这一次的次数…") }}</div><template v-else-if="state.offer.quote"><p class="qvs-offer-price">{{ voiceCharge(state.offer.quote,vt) }}</p><p>{{ vt("共 {p0} 字符，将分成 {p1} 段生成。整次完成后只结算本次确认的次数。",{p0:state.offer.quote.chars,p1:state.offer.quote.segments}) }}</p></template><p v-if="state.offer.error" class="qvs-inline-error" role="alert">{{ vt(state.offer.error) }}</p><label v-if="state.offer.quote" class="qvs-stream-choice"><input v-model="state.playWhileGenerating" type="checkbox"/>{{ vt("边生成边播放") }}<small>{{ vt("暂停播放不会停止生成，停止生成使用独立按钮。浏览器限制播放时，可亲自点击播放。") }}</small></label><small>{{ vt("这份确认使用上面保存的内容。编辑区的新修改会继续保留。") }}</small><footer><button type="button" class="qvs-secondary" @click="work.reject">{{ vt("再想一想") }}</button><button type="button" class="qvs-primary" :disabled="state.offer.loading||!state.offer.quote||!!state.offer.error" @click="work.approve">{{ vt("确认，开始生成") }} <ClientIcon name="arrowUpRight"/></button></footer></template></dialog>
  <dialog ref="clearDialog" class="qvs-review" aria-labelledby="qvs-clear-title" @cancel.prevent="state.clearReview=false"><h2 id="qvs-clear-title">{{ vt("给下一个想法，腾出一张纸？") }}</h2><p>{{ vt("只会清空当前编辑区。已经提交的声音任务和收藏室记录会继续保留。") }}</p><footer><button type="button" class="qvs-secondary" @click="state.clearReview=false">{{ vt("先留着") }}</button><button type="button" class="qvs-primary" @click="work.clearDraft">{{ vt("清空这张纸") }}</button></footer></dialog>
  <dialog ref="transferDialog" class="qvs-review" aria-labelledby="qvs-transfer-title" @cancel.prevent="work.keepDraft"><h2 id="qvs-transfer-title">{{ vt("把收藏室的这段文字，带到这里？") }}</h2><p>{{ vt("当前编辑区还有内容。你可以保留它，或明确换成刚才选择的那一段。") }}</p><footer><button type="button" class="qvs-secondary" @click="work.keepDraft">{{ vt("保留当前文字") }}</button><button type="button" class="qvs-primary" @click="work.adoptTransfer">{{ vt("换成收藏室的文字") }}</button></footer></dialog>
 </section>
</template>
<script setup>
import {voiceText as vt} from "../i18n/voice.js";
import {computed,ref,watch,nextTick} from 'vue';
import '../components/design/voice-progressive.css';
import {VOICES,voiceName,voiceDuration,voiceCharge,voiceTerminal,voiceTaskLabel,voicePlaybackLabel} from '../lib/voice-presentation.js';
import {useAppearance} from '../stores/appearance.js';
import {useVoiceComposer} from '../composables/useVoiceComposer.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import QLoader from '../components/QLoader.vue';
import '../components/design/voice-composer.css';
const appearance=useAppearance(),audio=ref(null),review=ref(null),clearDialog=ref(null),transferDialog=ref(null),work=useVoiceComposer(audio),{state,busy}=work;
const selectedVoice=computed(()=>VOICES.find(row=>row.id===state.draft.voice)||VOICES[2]);
for(const [value,element]of [[()=>state.offer,review],[()=>state.clearReview,clearDialog],[()=>state.transfer,transferDialog]])watch(value,async open=>{await nextTick();if(open&&!element.value?.open)element.value?.showModal?.();else if(!open&&element.value?.open)element.value.close();});
</script>
